import{_ as r,l as n,o as t,c as i,v as e,p as s,x as l,d as u,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"自动赎回 autocallable","description":"","frontmatter":{"title":"自动赎回 autocallable","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/autocallable.md","filePath":"quant/autocallable.md","lastUpdated":1789023840000}'),d={name:"quant/autocallable.md"};function E(h,a,B,A,m,_){const o=n("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="自动赎回-autocallable" tabindex="-1">自动赎回 autocallable <a class="header-anchor" href="#自动赎回-autocallable" aria-label="Permalink to &quot;自动赎回 autocallable&quot;">​</a></h1><div class="epigraph"><p>自动赎回是离散观察上的敲出：碰到上沿就终止并支付票息，否则继续；下跌侧再叠加敲入，就变成雪球一类的零售结构。</p><footer>—— 障碍与离散观察见 Broadie, Glasserman and Kou；结构分解见结构票据实务，对照境内雪球收益凭证</footer></div><p><a href="/quant/cliquet-forward-start">上一课</a>的重置仍让合约活到最后一段。Autocallable 的缺口是<strong>提前终止</strong>：观察日若 \\(S_{t_i}\\ge B_{\\mathrm{out}}\\)，合约结束，支付本金加票息。境内雪球在此之上再加敲入看跌，前沿课 <a href="/quant/snowball-pricing">雪球结构与定价</a> 已经写过完整三条终局。本课只补课程序列上的位置：把 autocall 当一般机制，与雪球条款对齐，不把雪球公式再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有敲入的纯 autocall（「凤凰」一类）近似：持有债券，卖出一串离散上障碍的敲出权，用票息当期权费。有敲入则再卖一份向下敲入看跌。问题是观察网格、票息是否记忆（memory / catch-up）、以及是否允许「已敲入仍可敲出」。这些条款改变的是路径集合，不是把票息贴现成债券收益率。</p><p>把 autocallable 当 cliquet，漏掉终止：后面观察日的票息在已敲出路径上不存在，Vega 期限结构在近端观察日堆得更尖。把 autocallable 当连续障碍，漏掉离散漏检，监控课已经警告过。</p><h3 id="票息是或有的-不是-coupon-strip" tabindex="-1">票息是或有的，不是 coupon strip <a class="header-anchor" href="#票息是或有的-不是-coupon-strip" aria-label="Permalink to &quot;票息是或有的，不是 coupon strip&quot;">​</a></h3><p>记忆条款：若本次未敲出但上次也未付息，可能把未付票息累加到下一次敲出。这使支付依赖整段观察历史，状态要包括「已累计未付票息」与「是否已敲入」。PDE 维度立刻上去，实务以 <a href="/quant/mc-pricing">蒙特卡洛</a> 为主。不要用连续 Reiner–Rubinstein 八公式去估每月观察的 autocall。</p><p><span class="marginnote">发行人在敲出日终止，切断的是投资者剩余的上侧与时间价值。票息高往往对应敲入近、挂钩高波指数、或观察稀疏。用历史敲出频率去外推票息兑现率，忽略了卖出时隐波已经把未敲出路径标贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在合约列出的观察日 \\(\\{t_i\\}\\) 上检查敲出；敲入按日收盘或连续，以条款为准。风险中性期望对：敲出停时的票息与本金、到期未敲出未敲入的票息、到期已敲入的下跌参与，分别贴现。模型用与香草一致的局部波动或混合，并对照随机波动——autocall 对远期偏斜与缺口（跳空越过障碍）敏感。离散观察的连续性修正可当快速报价，生产仍应在真实网格上模拟。</p><p>对冲：观察日前的数字/障碍 Gamma、敲入后的 Delta 跳变、以及票息的利率与融资。发行人侧的希腊值见 <a href="/quant/snowball-dealer-hedging">雪球发行人的对冲</a>，本课不重写交易台流程。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每条路径在观察网格上被吸收或继续。活着的路径集合随时间缩小（已敲出的不再贡献），又可能在敲入后改变支付类型。价值对 \\(B_{\\mathrm{out}}\\) 附近的密度几乎是一触即付，对 \\(B_{\\mathrm{in}}\\) 附近是敲入看跌。因此 autocallable 的隐波风险是<strong>障碍点上的数字风险 + 剩余期限的香草风险</strong>，不能收成一个 ATM Vega。</p>',14)),(t(),s(p,null,{default:l(()=>[c(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Obs%5B%22%E8%A7%82%E5%AF%9F%E6%97%A5%E7%BD%91%E6%A0%BC%22%5D%20--%3E%20Out%5B%22%E8%A7%A6%E5%8F%8A%E6%95%B2%E5%87%BA%20%E7%BB%88%E6%AD%A2%E4%BB%98%E6%81%AF%22%5D%0A%20%20Obs%20--%3E%20Cont%5B%22%E6%9C%AA%E6%95%B2%E5%87%BA%E5%88%99%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20Cont%20--%3E%20In%5B%22%E6%98%AF%E5%90%A6%E5%B7%B2%E6%95%B2%E5%85%A5%22%5D%0A%20%20In%20--%3E%20Down%5B%22%E5%88%B0%E6%9C%9F%E4%B8%8B%E8%B7%8C%E5%8F%82%E4%B8%8E%22%5D%0A%20%20In%20--%3E%20Bond%5B%22%E5%88%B0%E6%9C%9F%E8%BF%98%E6%9C%AC%E4%BB%98%E6%81%AF%22%5D%0A%20%20Out%20--%3E%20Stop%5B%22%E5%90%8E%E7%BB%AD%E7%A5%A8%E6%81%AF%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跳空、停牌、涨跌停使「收盘是否触及」与连续路径不一致，合同必须定义用哪一个价。多标的最差表现（worst-of）autocall 把相关变成一等风险，篮子课的符号在这里是：相关下降，worst-of 更易敲入、更难一起敲出，结构更便宜（对卖方更贵）。不要用单资产闭式去估 worst-of。</p><p>适当性、不得宣传保本、柜台衍生品规范是约束。本课不讨论如何改写条款以绕过适当性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Autocallable 是离散敲出加可选敲入；票息是或有期权费，不是债券 coupon。</li><li>状态含观察历史、已敲入与记忆票息；生产估值用合约网格上的模拟。</li><li>雪球是该类在境内的常见包装，细节不在本课重复推导。</li><li>出处：离散障碍修正见 Broadie, Glasserman and Kou, <em>Mathematical Finance</em>, 1997；结构分解见雪球与结构票据实务。</li></ul>',5))])}const q=r(d,[["render",E]]);export{f as __pageData,q as default};
